// Filter2: Filtra solo item con keep=true E confidence>=0.7
return $input.all().filter(item => {
  const keep = item.json.output?.keep === true;
  const confidence = Number(item.json.output?.confidence) || 0;
  return keep && confidence >= 0.7;
}).map(item => ({ json: item.json }));

return $input.all().map(item => {
  // 1. Diamo priorità assoluta all'URL esterno (property_url) rispetto a quello di Notion
  const externalUrl = item.json.property_url || item.json.URL || item.json.url || "";

  // 2. Mapping dei restanti campi usando i nomi corretti restituiti dal trigger
  const title = item.json.property_title || item.json.Title || item.json.title || "Titolo mancante";
  const reason = item.json.property_ai_reason || item.json["AI Reason"] || "Nessun motivo specificato";
  const notionId = item.json.id || "";

  return {
    json: {
      url: externalUrl,
      title: title,
      reason: reason,
      notion_id: notionId
    }
  };
});

// Merger v3: Ottimizzato per l'output del nodo Aggregate
const inputData = $input.first().json.data; // Accede all'array creato dall'Aggregate
let mergedContext = "### FONTI SELEZIONATE DALL'EDITOR (Tu):\n\n";
let counter = 0;

if (!Array.isArray(inputData)) {
  return [{ json: { error: "Dati non trovati nell'array 'data'" } }];
}

for (const item of inputData) {
  counter++;

  // Estrazione dati dalla struttura Jina nidificata nell'Aggregate
  const title = item.data?.title || "Titolo non disponibile";
  const url = item.data?.url || "Link non disponibile";
  const content = item.data?.content || "Contenuto non disponibile";

  // Nota: Se 'reason' non è stato aggregato nel nodo precedente, 
  // potrebbe essere necessario aggiungerlo alla configurazione dell'Aggregate
  const reason = item.reason || "Analisi tecnica approvata";

  mergedContext += `--- ARTICOLO ${counter} ---\n`;
  mergedContext += `🔹 TITOLO: ${title}\n`;
  mergedContext += `🔗 LINK: ${url}\n`;
  mergedContext += `🧠 PERCHÉ È RILEVANTE: ${reason}\n`;
  mergedContext += `\n📄 CONTENUTO COMPLETO:\n${content}\n`;
  mergedContext += `----------------------\n\n`;
}

return [{
  json: {
    combined_context: mergedContext,
    source_count: counter,
    status: "Ready for Writing"
  }
}];

// Code Formatter v9 - OTTIMIZZATO PER GOOGLE DRIVE
let rawContent = $input.item.json.output || $input.item.json.text || "";

if (!rawContent) return [{ json: { title: "Errore", status: "error" } }];

let cleanString = rawContent.replace(/```json|```/g, "").trim();

try {
  const parsedData = JSON.parse(cleanString);
  let finalPost = "";

  if (typeof parsedData.linkedin_post === 'object') {
    const p = parsedData.linkedin_post;
    let corpoString = Array.isArray(p.Corpo) ? p.Corpo.join("\n\n") : (p.Corpo || "");
    finalPost = `${p.Hook || ""}\n\n${corpoString}\n\n${p.Closing || ""}\n\n${p.Hashtag || ""}`;
  } else {
    finalPost = parsedData.linkedin_post || cleanString;
  }

  // Pulizia e formattazione
  finalPost = finalPost.replace(/\*\*/g, "").replace(/\*/g, "").replace(/\n{3,}/g, "\n\n").trim();

  return [{
    json: {
      title: parsedData.title || "Post Tecnico",
      post_preview: finalPost.substring(0, 1900) + "...",
      post_full: finalPost, // TESTO INTEGRALE PER GOOGLE DRIVE
      status: "success"
    }
  }];
} catch (e) {
  return [{ json: { title: "⚠️ ERRORE JSON", post_full: rawContent, status: "error" } }];
}

